import{_ as i,C as c,o as l,c as n,j as t,a as e,E as o,a5 as r}from"./chunks/framework.CyyS6Zdm.js";const q=JSON.parse('{"title":"复选框","description":"","frontmatter":{},"headers":[],"relativePath":"components/checkbox.md","filePath":"components/checkbox.md","lastUpdated":1787315667000}'),b={name:"components/checkbox.md"},s={id:"复选框",tabindex:"-1"};function u(k,d,x,p,m,f){const h=c("Badge"),a=c("XhDemo");return l(),n("div",null,[t("h1",s,[d[0]||(d[0]=e("复选框 ",-1)),o(h,{type:"info",text:"checkbox"}),d[1]||(d[1]=e()),d[2]||(d[2]=t("a",{class:"header-anchor",href:"#复选框","aria-label":'Permalink to "复选框 <Badge type="info" text="checkbox" />"'},"​",-1))]),d[3]||(d[3]=r('<p>一个可以选中、不选中、也可以处于半选的独立开关。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>表单里的单项同意、单项开关，且要随表单提交。</li><li>需要表达&quot;部分选中&quot;（全选框对应下面几项只勾了一部分）。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>开关立即生效、且是一项设置：用<a href="./switch">开关</a>。</li><li>几个互斥项里选一个：用<a href="./radio-group">单选组</a>。</li><li>一组多选项：用<a href="./checkbox-group">复选框组</a>，它管值的汇总。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>三态：选中、未选中、半选（<code>indeterminate</code>）。</li><li><code>hidden-input</code> 承担表单参与，<code>name</code> / <code>value</code> 照常提交。</li><li><code>readOnly</code> 与 <code>disabled</code> 不同：只读仍能聚焦、仍被提交。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>不传 checked 即为非受控</p>',10)),o(a,{src:"checkbox/01-basic"}),d[4]||(d[4]=t("h3",{id:"三态",tabindex:"-1"},[e("三态 "),t("a",{class:"header-anchor",href:"#三态","aria-label":'Permalink to "三态"'},"​")],-1)),d[5]||(d[5]=t("p",null,'checked 传 "indeterminate" 表示部分选中，它不是第三个稳定态：点一下就落到 true',-1)),o(a,{src:"checkbox/02-indeterminate"}),d[6]||(d[6]=t("h3",{id:"语气",tabindex:"-1"},[e("语气 "),t("a",{class:"header-anchor",href:"#语气","aria-label":'Permalink to "语气"'},"​")],-1)),d[7]||(d[7]=t("p",null,"tone 决定选中态的底与描边用哪族颜色，所以这里都置为选中",-1)),o(a,{src:"checkbox/03-tone"}),d[8]||(d[8]=t("h3",{id:"尺寸",tabindex:"-1"},[e("尺寸 "),t("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),d[9]||(d[9]=t("p",null,"size 同时缩放方框与勾选标记，不写就是缺省档",-1)),o(a,{src:"checkbox/04-size"}),d[10]||(d[10]=t("h3",{id:"事件",tabindex:"-1"},[e("事件 "),t("a",{class:"header-anchor",href:"#事件","aria-label":'Permalink to "事件"'},"​")],-1)),d[11]||(d[11]=t("p",null,"checked-change 带一份 { checked }，非受控时内部翻转也照发一次",-1)),o(a,{src:"checkbox/05-event"}),d[12]||(d[12]=t("h3",{id:"业务取值",tabindex:"-1"},[e("业务取值 "),t("a",{class:"header-anchor",href:"#业务取值","aria-label":'Permalink to "业务取值"'},"​")],-1)),d[13]||(d[13]=t("p",null,"checked 只认布尔，在中间换一道，进出两头拿到的都是业务值",-1)),o(a,{src:"checkbox/06-value-mapping"}),d[14]||(d[14]=t("h3",{id:"命令式聚焦",tabindex:"-1"},[e("命令式聚焦 "),t("a",{class:"header-anchor",href:"#命令式聚焦","aria-label":'Permalink to "命令式聚焦"'},"​")],-1)),d[15]||(d[15]=t("p",null,"节点由作者自己写，DOM 引用因此拿得到：聚焦、失焦与翻转都走命令式",-1)),o(a,{src:"checkbox/07-focus"}),d[16]||(d[16]=t("h3",{id:"随表单提交",tabindex:"-1"},[e("随表单提交 "),t("a",{class:"header-anchor",href:"#随表单提交","aria-label":'Permalink to "随表单提交"'},"​")],-1)),d[17]||(d[17]=t("p",null,"给了 name 才生出表单影子：勾上才提交，半选按未勾处理，与原生复选框一致",-1)),o(a,{src:"checkbox/08-form"}),d[18]||(d[18]=r('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-checkbox&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhCheckbox</code></td></tr><tr><td>组合式函数</td><td><code>useCheckbox</code></td></tr><tr><td>状态机</td><td><code>checkboxMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/checkbox.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;checkbox&quot;</code>：<strong><code>root</code></strong> · <code>indicator</code> · <code>hidden-input</code> · <code>label</code> · <code>text</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>checked</code></td><td><code>CheckboxCheckedState</code></td><td></td><td></td></tr><tr><td><code>defaultChecked</code></td><td><code>CheckboxCheckedState</code></td><td></td><td></td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td><td>只读：勾不动，但仍可聚焦、仍参与提交，对比度不降。</td></tr><tr><td><code>invalid</code></td><td><code>boolean</code></td><td></td><td>校验失败：只改呈现，不挡交互。</td></tr><tr><td><code>required</code></td><td><code>boolean</code></td><td></td><td>必填：随表单校验一起用，只发无障碍属性，不自行拦提交。</td></tr><tr><td><code>name</code></td><td><code>string</code></td><td></td><td>表单字段名；给了 hidden-input 才带 name 并参与提交。</td></tr><tr><td><code>value</code></td><td><code>string</code></td><td></td><td>提交出去的值，缺省 &#39;on&#39;，与原生复选框一致。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定选中态用哪族颜色。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，决定方框边长与勾的字号档位。</td></tr><tr><td><code>onCheckedChange</code></td><td><code>(details: CheckboxCheckedChangeDetails) =&gt; void</code></td><td></td><td>checked 变化意图回调；受控时是唯一出口，非受控随内部转移一并通知。</td></tr></tbody></table><h2 id="事件-1" tabindex="-1">事件 <a class="header-anchor" href="#事件-1" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>checked-change</code></td><td><code>CheckboxCheckedChangeDetails</code></td><td>checked 状态变化；detail 为 <code>{ checked: boolean }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhCheckbox</code></td><td><code>default</code></td><td>—</td><td>方框旁的文字；不写就只有一个方框。</td></tr><tr><td><code>XhCheckbox</code></td><td><code>indicator</code></td><td>—</td><td>方框里的图形；不写由皮肤画勾。</td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;indeterminate&#39; | &#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>indicator</code></td><td>&#39;indeterminate&#39; | &#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>label</code></td><td>&#39;indeterminate&#39; | &#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>text</code></td><td>&#39;indeterminate&#39; | &#39;checked&#39; | &#39;unchecked&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>off</code> · <code>on</code> · <code>indeterminate</code></p><p><strong>事件</strong>：<code>TOGGLE</code> · <code>CHECK</code> · <code>UNCHECK</code> · <code>CONTROLLED.ON</code> · <code>CONTROLLED.OFF</code> · <code>CONTROLLED.INDETERMINATE</code> · <code>FORM.RESET</code></p><p><strong>判据</strong>：<code>isCheckedControlled</code> · <code>defaultsToChecked</code> · <code>defaultsToIndeterminate</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useCheckbox</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>checked</code></td><td><code>CheckboxCheckedState</code></td><td></td></tr><tr><td><code>setChecked</code></td><td><code>(next: boolean) =&gt; void</code></td><td>半选只能由 checked prop 给出，这里只接受全选 / 全不选。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getIndicatorProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getHiddenInputProps</code></td><td><code>() =&gt; T[&#39;input&#39;]</code></td><td>表单影子：勾上才提交，半选按未勾处理。给了 name 才带 name。</td></tr><tr><td><code>getLabelProps</code></td><td><code>() =&gt; T[&#39;label&#39;]</code></td><td>包住方框与文字的 &lt;label&gt;：点文字即切换，方框的可及名从文字来。只在带文字时渲染。</td></tr><tr><td><code>getTextProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>方框旁的文字。</td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/checkbox/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Space</code> / <code>Enter</code></td><td>focus in root, not disabled</td><td>切换 checked 状态</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-checked</code></td><td>&#39;mixed&#39; | &#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>aria-invalid</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>aria-readonly</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>aria-required</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;checkbox&#39;</td></tr><tr><td><code>indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/checkbox.css</code> 按部件选择：<code>[data-scope=&quot;checkbox&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-required</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;indeterminate&#39; | &#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>indicator</code></td><td><code>data-state</code></td><td>&#39;indeterminate&#39; | &#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>label</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>label</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>label</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>label</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>label</code></td><td><code>data-state</code></td><td>&#39;indeterminate&#39; | &#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>text</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>text</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>text</code></td><td><code>data-state</code></td><td>&#39;indeterminate&#39; | &#39;checked&#39; | &#39;unchecked&#39;</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-checkbox-bg</code> · <code>--xh-checkbox-bg-checked</code> · <code>--xh-checkbox-border</code> · <code>--xh-checkbox-border-checked</code> · <code>--xh-checkbox-border-invalid</code> · <code>--xh-checkbox-fg</code> · <code>--xh-checkbox-fg-invalid</code> · <code>--xh-checkbox-indicator-fg</code> · <code>--xh-checkbox-label-fg</code> · <code>--xh-checkbox-label-fg-disabled</code> · <code>--xh-checkbox-label-font-size</code> · <code>--xh-checkbox-label-gap</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>外面套<a href="./field">表单字段</a>；成组时用<a href="./checkbox-group">复选框组</a>；在<a href="./table">表格</a>里做行选择。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>标签点得动——把文字放进 <code>label</code> 部件，别只让方框可点。</li><li>半选只用来表达&quot;下级部分选中&quot;，不要拿它当第三种业务状态。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>用单个复选框表达二选一（是 / 否）：用<a href="./radio-group">单选组</a>，两个选项都要能被读出来。</li><li>勾上就立刻发请求却不给反馈。</li></ul>',46))])}const P=i(b,[["render",u]]);export{q as __pageData,P as default};
